import math
def control(obs):
    h=obs['hitch_deg']
    cam=obs.get('views',{}).get('camera') or {}
    pts=cam.get('walls',[])
    left=[]; right=[]
    for b,d in pts:
        x=d*math.cos(math.radians(b)); y=d*math.sin(math.radians(b))
        if -5.5 < x < -1.0:
            (left if y>0 else right).append(y)
    desired=0
    if left and right:
        center=(min(left)+max(right))/2
        desired=max(-14,min(14, -5*center))
    steer=max(-28,min(28,2.4*(h-desired)))
    return steer,-0.65,-23

